import { useState, useEffect } from 'react'
import { PinInputWrapper } from './index.style'
import { CustomText, Container } from '../../../../components'
import { NotificationContainer } from 'react-notifications'
import { getFromLocalStorageData } from '../../../../helpers/localstorage'
import { useSelector, useDispatch } from 'react-redux'
import AuthActions from '../../../../redux/auth/action'
import ErrorActions from '../../../../redux/error/action'
import { REGISTRATION_DATA } from '../../../../constants/cookies'
import OjkFooter from '../../../../components/OjkFooter'
import PinInput from '../../../../components/PinInput'
import { useHistory } from 'react-router'
import ShowSnackbar from '../../../../components/ShowNotification'

function PinContainer ({ location }) {
  const [error, setError] = useState(false)
  const [step, setStep] = useState(1)
  const [pin, setPin] = useState('')

  const crypto = require('crypto')
  const dispatch = useDispatch()
  const history = useHistory()

  const registrationData = getFromLocalStorageData(REGISTRATION_DATA) || {}

  const createPinLoading = useSelector(state => state.Loading.CREATE_PIN)
  const createPinError = useSelector(state => state.Error.CREATE_PIN)
  // const createPinStatus = useSelector(state => state.Auth.createPinStatus)

  useEffect(() => {
    if (createPinLoading === false && createPinError === false) {
      history.push('/new-pin-success')
    }
    if (createPinError && createPinLoading === false) {
      ShowSnackbar.error({
        visible: true,
        text: 'Request tidak dapat diproses, silahkan coba lagi'
      })
      dispatch(ErrorActions.resetErrorRedux(['CREATE_PIN']))
    }
  }, [createPinLoading, createPinError])

  useEffect(() => {
    return () => {
      clearInterval()
    }
  }, [])

  const hashString = (input) => {
    return crypto.createHash('sha256').update(input).digest('hex')
  }

  const handleBackButton = () => {
    if (step === 2) {
      setStep(1)
      setError(false)
    }
  }

  const handlePin = (value) => {
    setPin(value)
    setStep(2)
  }

  const handleSubmit = (value) => {
    if (value === pin) {
      dispatch(AuthActions.createPin({
        phone_no: registrationData.phone_no,
        pin: hashString(value),
        operation_id: registrationData.operation_id,
        otp: registrationData.otp
      }))
    } else {
      setError(true)
    }
  }

  return (
    <Container
      title={step === 1 ? 'Buat PIN Baru' : 'Konfirmasi PIN'}
      showInnerHeader
      hideBackButton={step === 1}
      loader={createPinLoading}
      onBackClick={handleBackButton}
    >
      <PinInputWrapper location={location.pathname === '/login/pin'}>
        <CustomText size={12} weight={500} textAlign='center' top='36%' bottom='8%'>
          {step === 1
            ? 'Masukkan 4 digit angka untuk membuat PIN baru. PIN akan digunakan untuk otentikasi masuk aplikasi, proses pembayaran dan konfirmasi lainnya.'
            : 'Masukkan kembali 4 digit PIN untuk konformasi.'}
        </CustomText>
        {
          step === 1 &&
            <PinInput onComplete={handlePin} />
        }
        {
          step === 2 &&
            <>
              <PinInput
                onComplete={handleSubmit}
                error={error}
                setError={setError}
              />
              {
                error &&
                  <CustomText size={12} weight={500} textAlign='center' top='20px' bottom='' color='#DC0000'>
                    PIN tidak sama dengan yang sebelumnya.
                  </CustomText>
              }
            </>
        }
        <OjkFooter />
        <NotificationContainer />
      </PinInputWrapper>
    </Container>
  )
}

export default PinContainer
